"""slottedBlock_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +x from 2 extrusion(s) and 0 cut(s), applied in order;
each is an outline in the yz plane between two levels. Units: mm.
Run:  python slottedBlock_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Solid, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along x
z1 = 18.0    # level along x
z2 = 28.0    # level along x

DIR = (1, 0, 0)


def P(a, b):
    """Point (y, z) in the sketch plane (x = 0)."""
    return (0, a, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: x 0.0 to 18.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(55.9284, -55.634), P(51.6607, -64.786)),
    cf.segment(P(51.6607, -64.786), P(19.0337, -49.5717)),
    cf.segment(P(19.0337, -49.5717), P(16.9205, -54.1033)),
    cf.segment(P(16.9205, -54.1033), P(49.5476, -69.3175)),
    cf.segment(P(49.5476, -69.3175), P(45.4989, -78.0)),
    cf.segment(P(45.4989, -78.0), P(0.0, -78.0)),
    cf.segment(P(0.0, -78.0), P(0.0, 0.0)),
    cf.segment(P(0.0, 0.0), P(16.0, 0.0)),
    cf.segment(P(16.0, 0.0), P(16.0, -24.0)),
    cf.segment(P(16.0, -24.0), P(34.0, -24.0)),
    cf.segment(P(34.0, -24.0), P(34.0, -40.0)),
    cf.segment(P(34.0, -40.0), P(58.0, -51.1914)),
    cf.segment(P(58.0, -51.1914), P(55.9284, -55.634)),
)
part = prism(outline_1, z0, z1)

# ---- 2. extrusion: x 18.0 to 28.0 ------------------------------
outline_2 = cf.wire(
    cf.segment(P(16.9205, -54.1033), P(19.0336, -49.5717)),
    cf.segment(P(19.0336, -49.5717), P(51.6607, -64.786)),
    cf.segment(P(51.6607, -64.786), P(58.0, -51.1914)),
    cf.segment(P(58.0, -51.1914), P(8.0, -27.876)),
    cf.segment(P(8.0, -27.876), P(8.0, 0.0)),
    cf.segment(P(8.0, 0.0), P(0.0, 0.0)),
    cf.segment(P(0.0, 0.0), P(0.0, -78.0)),
    cf.segment(P(0.0, -78.0), P(45.4989, -78.0)),
    cf.segment(P(45.4989, -78.0), P(49.5476, -69.3175)),
    cf.segment(P(49.5476, -69.3175), P(16.9205, -54.1033)),
)
part = part + prism(outline_2, z1, z2)

# ---- off-axis bosses and holes: (start point, axis direction, diameter, length) ----
for p, u, d, h, op in [
    ((7.0, 54.8304, -57.9887), (0.0, 0.9063078145, -0.4226182029), 6.0, 6.0, "add"),
    ((21.0, 54.8304, -57.9887), (0.0, 0.9063078145, -0.4226182029), 6.0, 6.0, "add"),
]:
    c = Solid.makeCylinder(d / 2, h, Vector(*p), Vector(*u))
    part = part + c if op == "add" else part - c

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "slottedBlock_exact.step")
